// Processar mensagem do Slack e extrair comando
const message = $input.item.json;
const text = (message.text || '').toUpperCase().trim();

// Padrões: APROVAR <ID> ou REJEITAR <ID>
const approveMatch = text.match(/APROVAR\s+([A-F0-9\-]+)/i);
const rejectMatch = text.match(/REJEITAR\s+([A-F0-9\-]+)/i);

let action = null;
let reportId = null;

if (approveMatch) {
  action = 'approve';
  reportId = approveMatch[1];
} else if (rejectMatch) {
  action = 'reject';
  reportId = rejectMatch[1];
}

if (!action || !reportId) {
  return [{ json: { skip: true, reason: 'Comando não reconhecido' } }];
}

return [{
  json: {
    action: action,
    reportId: reportId,
    userId: message.user || message.user_id,
    userName: message.user_name || 'Unknown',
    channel: message.channel || message.channel_id,
    timestamp: message.ts || new Date().toISOString(),
    originalMessage: message.text
  }
}];

// Formatar mensagem de confirmação
const command = $('Processar Comando').item.json;
const report = $('Buscar Relatório').item.json[0];
const update = $input.item.json;

const action = command.action === 'approve' ? 'APROVADO' : 'REJEITADO';
const emoji = command.action === 'approve' ? '✅' : '❌';

let message = `${emoji} *Relatório ${action}*\n\n`;
message += `*ID:* ${command.reportId}\n`;
message += `*Aprovado por:* ${command.userName}\n`;
message += `*Data/Hora:* ${new Date().toLocaleString('pt-BR')}\n\n`;

if (report) {
  message += `*Especialista:* ${report.specialist_type === 'infra' ? 'Infraestrutura' : 'Desenvolvimento'}\n`;
  message += `*Severidade:* ${report.severity.toUpperCase()}\n`;

  if (command.action === 'approve') {
    const actionPlan = typeof report.action_plan === 'string' 
      ? JSON.parse(report.action_plan) 
      : report.action_plan;

    message += `\n*📋 Ações a serem executadas:*\n`;
    if (Array.isArray(actionPlan)) {
      for (let i = 0; i < Math.min(actionPlan.length, 5); i++) {
        message += `${i + 1}. ${actionPlan[i].description || 'Ação'}\n`;
      }
      if (actionPlan.length > 5) {
        message += `... e mais ${actionPlan.length - 5} ações\n`;
      }
    }

    message += `\n⚠️ *Ações requerem execução manual ou workflow adicional*\n`;
  }
}

return [{
  json: {
    message: message,
    channel: command.channel || '#credgestor-alerts',
    thread_ts: null
  }
}];

// Resumo da execução
const command = $('Processar Comando').item.json;
const update = $input.item.json;

return [{
  json: {
    executionTime: new Date().toISOString(),
    action: command.action,
    reportId: command.reportId,
    status: update.status || 'processed',
    processedBy: command.userName
  }
}];
